label("$A$",(sqrt(3),0),SE);
label("$B$",(0,1),NW);
label("$O$",(r1,r1),ESE);
label("$C$",(0,r1),W);
label("$D$",(0,0),SW);
label("$E$",(r1,0),S);
label("$F$",(r1,r1)+r1*dir(60),dir(60));
draw(rightanglemark((0,1),origin,(1,0),3));
draw((r1,r1)+r1*dir(60)--(r1,r1)--(0,r1));
draw((r1,0)--(r1,r1)--(0,1));
draw((r1,r1)--(0,1));
[/asy]

Since $a^2$ varies inversely with $b^3$, $(a^2)(b^3)=k$ for some constant $k$. If $a=7$ when $b=3$, then $k=(7^2)(3^3)=(49)(27)=1323$. So if $b=6$, \begin{align*} (a^2)(6^3)&=1323
\\ 216a^2&=1323
\\\Rightarrow\qquad a^2&=\boxed{6.125}
\end{align*}

